// --------------------------------------------------------------
//  TRADING APP CORE LOGIC (Alpine.js component)
//  - Manages balance, trades, chart rendering, local storage.
//  - Two chart modes: 'fullReset' (new random candles each bet)
//    and 'nextCandle' (predict direction, extend the chart).
//  - Edge = simulated win probability (50% to 90%), payout% configurable.
//  - 300‑trade backtest modal with equity/win‑rate visualization.
// --------------------------------------------------------------
function tradingApp() {
  return {
    // Reactive game state
    balance: 1000.00,
    wager: 10,
    winCount: 0,
    loseCount: 0,
    payoutPercent: 92,
    edgePercent: 50,
    outcomeMessage: '⚡ Ready — choose direction',
    outcomeType: 'idle',
    chart: null,
    candleSeries: null,
    candlesData: [],
    chartMode: 'fullReset',
    showTestModal: false,
    menuOpen: false,
    STORAGE_KEY: 'TradingGameState',
    testStats: {
      startingBalance: 0,
      finalBalance: 0,
      netPL: 0,
      wins: 0,
      losses: 0,
      observedWinRate: 0,
      totalWagered: 0,
      expectancy: 0,
      edgeUsed: 50,
      balanceHistory: [],
      winRateHistory: []
    },

    // ------------------------------------ PERSISTENCE ------------------------------------
    persistState() {
      try {
        localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
          balance: this.balance,
          wager: this.wager,
          winCount: this.winCount,
          loseCount: this.loseCount,
          payoutPercent: this.payoutPercent,
          edgePercent: this.edgePercent,
          chartMode: this.chartMode,
          candlesData: this.candlesData,
          outcomeMessage: this.outcomeMessage,
          outcomeType: this.outcomeType
        }));
      } catch(e) {}
    },

    loadStateFromStorage() {
      let raw = localStorage.getItem(this.STORAGE_KEY);
      if(!raw) return false;
      try {
        let s = JSON.parse(raw);
        if(typeof s.balance === 'number') this.balance = s.balance;
        if(typeof s.wager === 'number') this.wager = s.wager;
        if(typeof s.winCount === 'number') this.winCount = s.winCount;
        if(typeof s.loseCount === 'number') this.loseCount = s.loseCount;
        if(typeof s.payoutPercent === 'number') this.payoutPercent = s.payoutPercent;
        if(typeof s.edgePercent === 'number') this.edgePercent = s.edgePercent;
        if(s.chartMode === 'fullReset' || s.chartMode === 'nextCandle') this.chartMode = s.chartMode;
        if(Array.isArray(s.candlesData) && s.candlesData.length) this.candlesData = s.candlesData;
        if(typeof s.outcomeMessage === 'string') this.outcomeMessage = s.outcomeMessage;
        if(['win', 'loss', 'idle'].includes(s.outcomeType)) this.outcomeType = s.outcomeType;
        if(this.wager > this.balance && this.balance > 0) this.wager = Math.max(1, Math.floor(this.balance));
        return true;
      } catch(e) {
        return false;
      }
    },

    // ------------------------------------ CHART DATA GENERATION ------------------------------------
    generateRandomCandles(num = 55, startPrice = 100) {
      let candles = [];
      let prev = startPrice;
      for(let i = 0; i < num; i++) {
        let change = (Math.random() - 0.5) * 0.045;
        let close = +(prev * (1 + change)).toFixed(4);
        close = Math.max(close, 0.5);
        let high = +(Math.max(prev, close) * (1 + Math.random() * 0.015)).toFixed(4);
        let low = +(Math.min(prev, close) * (1 - Math.random() * 0.012)).toFixed(4);
        candles.push({
          time: i,
          open: +prev.toFixed(4),
          high: high,
          low: low,
          close: close
        });
        prev = close;
      }
      return candles;
    },

    updateChartFromData() {
      if(this.candleSeries) {
        if(!this.candlesData.length) this.candlesData = this.generateRandomCandles(55, 100);
        this.candleSeries.setData(this.candlesData);
        if(this.chart) this.chart.timeScale().fitContent();
      }
    },

    // For "Next Candle" mode: generate one candle based on prediction & win outcome
    generateNextCandle(prediction, isWin, prevClose) {
      let targetUp = (prediction === 'up' && isWin) || (prediction === 'down' && !isWin);
      let move = 0.002 + Math.random() * 0.038;
      let close = targetUp ? prevClose * (1 + move) : prevClose * (1 - move);
      close = Math.max(0.25, +close.toFixed(4));
      let high = +(Math.max(prevClose, close) * (1 + Math.random() * 0.018)).toFixed(4);
      let low = +(Math.min(prevClose, close) * (1 - Math.random() * 0.014)).toFixed(4);
      return {
        time: this.candlesData.length,
        open: +prevClose.toFixed(4),
        high: high,
        low: low,
        close: close
      };
    },

    generateRandomCandle(prevClose) {
      let up = Math.random() < 0.5;
      let move = 0.002 + Math.random() * 0.042;
      let close = up ? prevClose * (1 + move) : prevClose * (1 - move);
      close = Math.max(0.25, +close.toFixed(4));
      let high = +(Math.max(prevClose, close) * (1 + Math.random() * 0.018)).toFixed(4);
      let low = +(Math.min(prevClose, close) * (1 - Math.random() * 0.014)).toFixed(4);
      return {
        time: this.candlesData.length,
        open: +prevClose.toFixed(4),
        high: high,
        low: low,
        close: close
      };
    },

    skipToNextCandle() {
      if(this.chartMode !== 'nextCandle') {
        this.outcomeMessage = 'Skip only in Next Candle Mode';
        return;
      }
      if(!this.candlesData.length) this.candlesData = this.generateRandomCandles(20, 100);
      let last = this.candlesData[this.candlesData.length - 1];
      let newCandle = this.generateRandomCandle(last.close);
      this.candlesData.push(newCandle);
      this.updateChartFromData();
      this.outcomeMessage = `⏩ Skipped → ${newCandle.close > newCandle.open ? '📈 BULLISH' : '📉 BEARISH'} (no balance change)`;
      this.outcomeType = 'idle';
      this.persistState();
    },

    // Chart mode switching
    setChartMode(mode) {
      this.chartMode = mode;
      this.outcomeMessage = `Mode: ${mode === 'fullReset' ? 'Full Refresh' : 'Next Candle'}`;
      if(this.chart) this.chart.timeScale().fitContent();
      this.persistState();
    },

    // ------------------------------------ CORE TRADING LOGIC ------------------------------------
    placeBet(prediction) {
      if(!this.canBet()) {
        this.outcomeMessage = '❌ Insufficient balance';
        return;
      }
      let wagerAmt = this.wager;
      let isWin = Math.random() < (this.edgePercent / 100);   // Edge = probability of winning
      let multiplier = this.payoutPercent / 100;
      let winAmount = 0;
      if(isWin) {
        winAmount = wagerAmt * multiplier;
        this.balance += winAmount;
        this.winCount++;
      } else {
        this.balance -= wagerAmt;
        this.loseCount++;
      }

      // Update chart based on selected mode
      if(this.chartMode === 'fullReset') {
        this.candlesData = this.generateRandomCandles(55, 95 + Math.random() * 20);
        this.updateChartFromData();
        this.outcomeMessage = isWin ? `🎉 WIN +$${winAmount.toFixed(2)} → $${this.balance.toFixed(2)}` : `📉 LOSS -$${wagerAmt.toFixed(2)} → $${this.balance.toFixed(2)}`;
      } else {
        let prevClose = this.candlesData[this.candlesData.length - 1].close;
        let newCandle = this.generateNextCandle(prediction, isWin, prevClose);
        this.candlesData.push(newCandle);
        this.updateChartFromData();
        this.outcomeMessage = isWin ? `🎉 WIN +$${winAmount.toFixed(2)} → $${this.balance.toFixed(2)}` : `📉 LOSS -$${wagerAmt.toFixed(2)} → $${this.balance.toFixed(2)}`;
      }
      this.outcomeType = isWin ? 'win' : 'loss';
      if(this.wager > this.balance && this.balance > 0) this.wager = Math.max(1, Math.floor(this.balance));
      if(this.balance <= 0) this.outcomeMessage += ' 💀 GAME OVER — press RESET';
      this.persistState();
    },

    canBet() {
      return this.balance > 0 && this.wager > 0 && this.wager <= this.balance && this.chart !== null;
    },

    // Wager helpers
    adjustWager(delta) {
      let v = this.wager + delta;
      if(v < 1) v = 1;
      if(v > this.balance) v = this.balance;
      this.wager = Math.floor(v);
      this.persistState();
    },

    syncWagerFromSlider(e) {
      let v = parseFloat(e.target.value);
      if(isNaN(v)) v = 1;
      v = Math.min(this.balance, Math.max(1, v));
      this.wager = Math.floor(v);
      this.persistState();
    },

    validateWagerFromInput() {
      let v = parseFloat(this.wager);
      if(isNaN(v)) v = 1;
      v = Math.min(this.balance, Math.max(1, v));
      this.wager = Math.floor(v);
      this.persistState();
    },

    setWager(amount) {
      this.wager = Math.min(this.balance, Math.max(1, amount));
      this.persistState();
    },

    winRate() {
      let t = this.winCount + this.loseCount;
      return t === 0 ? '0%' : ((this.winCount / t) * 100).toFixed(1) + '%';
    },

    resetGame() {
      this.balance = 1000;
      this.winCount = 0;
      this.loseCount = 0;
      this.wager = 10;
      this.payoutPercent = 92;
      this.edgePercent = 50;
      this.candlesData = this.generateRandomCandles(55, 100);
      this.outcomeMessage = '🔄 Game reset. Edge=50%';
      this.outcomeType = 'idle';
      this.updateChartFromData();
      this.persistState();
    },

    // ------------------------------------ CHART INIT (Lightweight Charts) ------------------------------------
    initChartAndLoad() {
      let container = document.getElementById('trading-chart');
      if(!container) return;
      this.chart = LightweightCharts.createChart(container, {
        layout: {
          background: { color: '#0a0e17' },
          textColor: '#d1d5db',
          fontSize: 10
        },
        grid: {
          vertLines: { color: '#1f2a3e' },
          horzLines: { color: '#1f2a3e' }
        },
        rightPriceScale: { borderColor: '#2a3a55' },
        timeScale: { borderColor: '#2a3a55', timeVisible: true },
        width: container.clientWidth,
        height: container.clientHeight
      });
      this.candleSeries = this.chart.addCandlestickSeries({
        upColor: '#26a69a',
        downColor: '#ef5350',
        borderDownColor: '#ef5350',
        borderUpColor: '#26a69a',
        wickDownColor: '#ef5350',
        wickUpColor: '#26a69a'
      });
      let hasSaved = this.loadStateFromStorage();
      if(!hasSaved || !this.candlesData.length) this.candlesData = this.generateRandomCandles(55, 100);
      this.updateChartFromData();
      if(this.wager > this.balance && this.balance > 0) this.wager = Math.max(1, Math.floor(this.balance));
      window.addEventListener('resize', () => this.resizeChart());
      new ResizeObserver(() => this.resizeChart()).observe(container);
    },

    resizeChart() {
      if(this.chart) {
        let container = document.getElementById('trading-chart');
        if(container) {
          this.chart.applyOptions({
            width: container.clientWidth,
            height: container.clientHeight
          });
          this.chart.timeScale().fitContent();
        }
      }
    },

    // Hotkey handler
    handleHotkey(e) {
      // Prevent when typing in input fields or when modals are open
      const activeTag = document.activeElement?.tagName;
      if (activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT') return;
      if (this.menuOpen || this.showTestModal) return;

      const key = e.key;

      // UP actions: ArrowUp OR 'b' (Buy)
      if (key === 'ArrowUp' || key === 'b' || key === 'B') {
        e.preventDefault();
        if (this.canBet()) this.placeBet('up');
      }
      // DOWN actions: ArrowDown OR 's' (Sell)
      else if (key === 'ArrowDown' || key === 's' || key === 'S') {
        e.preventDefault();
        if (this.canBet()) this.placeBet('down');
      }
      // SKIP candle: Space bar (only available in 'nextCandle' mode)
      else if (key === ' ' || key === 'Space') {
        e.preventDefault();  // prevents page scrolling
        if (this.chartMode === 'nextCandle' && this.chart && this.candlesData.length) {
          this.skipToNextCandle();
        }
      }
    },

    // Remove listener on page unload (cleanup)
    cleanupHotkeys() {
      window.removeEventListener('keydown', this.handleHotkey);
    },

    initApp() {
      this.initChartAndLoad();
      window.addEventListener('keydown', (e) => this.handleHotkey(e));
      window.addEventListener('unload', (e) => this.cleanupHotkeys());
      requestAnimationFrame(() => {
        this.resizeChart();
        if(this.chart) this.chart.timeScale().fitContent();
      });
    },

    shareApp() {
      if(navigator.share) {
        navigator.share({
          title: 'The Trading Game',
          text: 'Binary options simulator',
          url: window.location.href
        });
      } else {
        navigator.clipboard.writeText(window.location.href);
        this.outcomeMessage = '🔗 Link copied!';
        setTimeout(() => {
          if(this.outcomeMessage === '🔗 Link copied!') this.outcomeMessage = '⚡ Game ready';
        }, 1500);
      }
    },

    // ------------------------------------ 300-TRADE BACKTEST SIMULATOR ------------------------------------
    run300TradeTest() {
      let balance = this.balance;
      let wins = 0, losses = 0;
      let hist = [balance];
      let wrHist = [0];
      let wager = this.wager;
      let mult = this.payoutPercent / 100;
      let prob = this.edgePercent / 100;
      for(let i = 1; i <= 300; i++) {
        if(Math.random() < prob) {
          balance += wager * mult;
          wins++;
        } else {
          balance -= wager;
          losses++;
        }
        hist.push(balance);
        wrHist.push((wins / i) * 100);
      }
      this.testStats = {
        startingBalance: this.balance,
        finalBalance: balance,
        netPL: balance - this.balance,
        wins: wins,
        losses: losses,
        observedWinRate: ((wins / 300) * 100).toFixed(2),
        totalWagered: wager * 300,
        expectancy: (balance - this.balance) / 300,
        edgeUsed: this.edgePercent,
        balanceHistory: hist,
        winRateHistory: wrHist
      };
      this.showTestModal = true;
      setTimeout(() => {
        this.drawEquityCurve();
        this.drawWinRateCurve();
      }, 80);
    },

    // Draw equity line on canvas
    drawEquityCurve() {
      let canvas = document.getElementById('equityCanvas');
      if(!canvas) return;
      let ctx = canvas.getContext('2d');
      let w = canvas.clientWidth;
      let h = canvas.clientHeight;
      canvas.width = w;
      canvas.height = h;
      let data = this.testStats.balanceHistory;
      if(!data.length) return;
      let minV = Math.min(...data);
      let maxV = Math.max(...data);
      let range = maxV - minV || 1;
      let stepX = w / (data.length - 1);
      ctx.clearRect(0, 0, w, h);
      ctx.beginPath();
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 2;
      for(let i = 0; i < data.length; i++) {
        let x = i * stepX;
        let y = h - ((data[i] - minV) / range) * h;
        if(i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    },

    // Draw rolling win rate with reference edge line
    drawWinRateCurve() {
      let canvas = document.getElementById('winrateCanvas');
      if(!canvas) return;
      let ctx = canvas.getContext('2d');
      let w = canvas.clientWidth;
      let h = canvas.clientHeight;
      canvas.width = w;
      canvas.height = h;
      let data = this.testStats.winRateHistory;
      if(!data.length) return;
      let stepX = w / (data.length - 1);
      ctx.clearRect(0, 0, w, h);
      ctx.beginPath();
      ctx.strokeStyle = '#f59e0b';
      ctx.lineWidth = 2;
      for(let i = 0; i < data.length; i++) {
        let x = i * stepX;
        let y = h - (data[i] / 100) * h;
        if(i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
      ctx.beginPath();
      ctx.strokeStyle = '#4ade80';
      ctx.setLineDash([5, 5]);
      let edgeY = h - (this.testStats.edgeUsed / 100) * h;
      ctx.moveTo(0, edgeY);
      ctx.lineTo(w, edgeY);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  };
}
